const p = drone.getPlayer();
const blockName = typeof wallBlock === 'string' ? wallBlock : 'cobblestone';
const length = typeof wallLength === 'number' ? wallLength : 5;
let placed = 0;
let missing = 0;
for (var dx = 0; dx < length; dx++) {
  const r = drone.placeBlock({ x: p.blockX + dx, y: p.blockY, z: p.blockZ + 2, block: blockName });
  if (r && r.placed) placed++; else missing++;
}
return { placed: placed, missing: missing, hint: missing ? 'gather ' + blockName + ' into the drone inventory first' : '' };
